"""47 explicit LEP reviews; articles50/52/54 stay pending for 2026 evidence."""
exec(compile(open('scripts/review/reviewed-course-overlay.py').read(),'reviewed-course-overlay.py','exec'))
add(48,'Autoridade da restritiva representa ao juiz por falta grave.','Representar não equivale a decretar automaticamente conversão,regressão ou perda de remição.','Administração decide sozinha todas as consequências judiciais? Não.','Poder disciplinar administrativo está previsto? Sim.')
add(49,'Norma local especifica falta leve e sua sanção anterior ao fato.','Não pode criar falta grave federal por analogia; tentativa recebe disciplina expressa.','A tentativa tem sanção da consumada? Sim.','Legislação local define livremente toda falta grave? Não.')
add(51,'Condenado injustificadamente retarda cumprimento de obrigação restritiva.','Impossibilidade comprovada não pode ser ignorada ao examinar injustificadamente.','Qualquer atraso basta por si? Não.','Há remissão aos deveresII/V do39? Sim.')
add(53,'Sanção escolhida é isolamento ou advertência entre modalidades legais.','Rol não autoriza cela escura,sanção coletiva ou dispensar competência adequada.','São cinco modalidades expressas? Sim.','RDD é simples isolamento administrativo comum? Não.')
add(55,'Bom comportamento e dedicação ao trabalho fundamentam recompensa.','Recompensa não se confunde com direito fundamental que independe de favor.','Colaboração com disciplina importa? Sim.','Saúde básica pode ser retirada por falta de recompensa? Não.')
add(56,'Elogio ou regalia é concedido sob regras locais aplicáveis.','Não confundir regalia com direito que a Administração não pode suprimir arbitrariamente.','Regulamento/local definem forma da regalia? Sim.','Qualquer prêmio elimina requisito legal de benefício judicial? Não.')
add(57,'Sanção é individualizada considerando circunstâncias e consequências da falta.','Falta grave não impõe automaticamente RDD sem seus requisitos próprios.','Tempo de prisão é critério previsto? Sim.','Gravidade dispensa motivação? Não.')
add(58,'Isolamento disciplinar ordinário respeita limite de trinta dias e comunicação judicial.','RDD tem ressalva legal própria,não o mesmo limite universal.','Isolamento deve sempre ser comunicado ao juiz? Sim.','Toda suspensão pode durar indefinidamente? Não.')
add(59,'Condenado é ouvido em audiência judicial com defensor eMP para apurar falta.','RE972598 admite dispensa do PAD prévio nesse recorte; não dispensa defesa nem apuração.','PAD é universalmente indispensável mesmo com audiência adequada? Não.','Dispensar PAD permite sanção sem contraditório? Não.')
add(60,'Administração determina isolamento preventivo de até dez dias nos pressupostos legais.','Inclusão preventiva emRDD depende de juiz; tempo preventivo conta na sanção.','Dez dias é o limite deste isolamento preventivo? Sim.','É possível desprezar tempo preventivo ao contar a sanção? Não.')
add(61,'Defensoria atua como órgão da execução,além do juiz eMP.','Conselho Nacional,Conselho Penitenciário eComunidade são órgãos distintos.','Defensoria integra o rol? Sim.','Os três conselhos são a mesma instituição? Não.')
add(62,'CNPCP tem sede na Capital da República e vínculo ministerial textual.','Conselho estadual não se tornaCNPCP pela atuação na mesma área.','Sede nacional é prevista? Sim.','Este artigo fixa sede obrigatória de todo conselho local? Não.')
add(63,'Membro doCNPCP tem mandato textual de dois anos.','Conselho Penitenciário do69 tem quatro anos; não copiar os prazos.','Composição textual é13 membros? Sim.','Renovação anual é total? Não;texto indica um terço.')
add(64,'CNPCP representa por interdição e propõe diretrizes.','Representação não é ordem judicial de interdição nem julgamento de progressão.','Pesquisa criminológica está entre atribuições? Sim.','Pode substituir automaticamente o juiz na interdição? Não.')
add(65,'Lei local identifica juiz competente para execução.','Na falta da indicação,há regra subsidiária do juiz da sentença; regras especiais de competência continuam a exigir exame.','Regra subsidiária é incondicional em toda execução? Não.','A organização judiciária local é referência expressa? Sim.')
add(66,'Juiz decide remição e aplica lei posterior favorável ao caso julgado.','Remissão antiga à conversão de multa não permite prisão só por inadimplemento; integrarCP51 atual.','Inspeção é mensal? Sim.','Multa inadimplida vira automaticamente prisão? Não.')
add(67,'MP fiscaliza execução e atua no incidente.','Fiscalizar não transforma todo requerimento em decisão judicial.','Medida de segurança também está incluída? Sim.','O MP substitui juiz nas decisões de progressão? Não.')
add(68,'MP visita unidade mensalmente e requer incidente de desvio.','Periodicidade não deve ser copiada para toda atuação de outros órgãos.','Presença é registrada em livro próprio? Sim.','MP decide sozinho a conversão ao requerê-la? Não.')
add(69,'Conselho Penitenciário fiscaliza e emite parecer,com membros nomeados pelo governador.','Não confundir mandato de quatro anos com dois anos doCNPCP.','É órgão consultivo? Sim.','É o próprio juiz da execução? Não.')
add(70,'Conselho apresenta relatório do exercício anterior no primeiro trimestre.','Parecer do indulto tem ressalva expressa para pedido baseado na saúde; emissão não é concessão do indulto.','Supervisiona patronatos? Sim.','Emite o decreto presidencial de indulto? Não.')
add(71,'Texto legal usaDEPEN para órgão executivo penitenciário nacional.','Portal institucional atual identificaSenappen; nome histórico não descreve sozinho a estrutura administrativa atual.','Órgão nacional tem função executiva no texto? Sim.','Nome histórico dispensa conferir organização atual? Não.')
add(72,'Órgão nacional fiscaliza e acompanha execução/progressão especial das mulheres.','Dados estatísticos não concedem automaticamente progressão nem eliminam regime fechado por si.','Coordenação de estabelecimentos federais está prevista? Sim.','Relatório de avaliação substitui requisitos judiciais da progressão? Não.')
add(73,'Lei local cria órgão penitenciário ou similar.','Artigo não obriga todo estado a usar exatamente a sigla federal.','Legislação local tem faculdade de criação? Sim.','O artigo cria diretamente cada cargo local? Não.')
add(74,'Órgão local supervisiona unidades e encaminha resultados do acompanhamento pertinente.','Competência local não significa coordenar sozinho todo sistema federal.','Há remissão ao acompanhamento das mulheres do72? Sim.','A remissão dá benefício automático a toda mulher presa? Não.')
add(75,'Diretor atende formação prevista,experiência e aptidão,idoneidade e dedicação integral.','Diploma sozinho não esgota requisitos; residência próxima é alternativa à residência na unidade.','Residir obrigatoriamente dentro da cela é requisito? Não.','Experiência administrativa é expressa? Sim.')
add(76,'Categorias funcionais são organizadas com atribuições especificadas.','Definir quadro não permite investidura arbitrária ou confusão entre direção e assessoramento.','Necessidades do serviço orientam organização? Sim.','Todo servidor tem as mesmas atribuições por este artigo? Não.')
add(77,'Pessoal recebe formação específica e reciclagem periódica.','Formação não autoriza ascender a outra carreira dispensando concurso; exceção técnica do§2º não é vedação universal de profissional masculino.','Há exceção para pessoal técnico especializado? Sim.','Curso sozinho autoriza qualquer provimento funcional? Não.')
add(78,'Patronato particular assiste egresso e albergado.','Não confundirpatronato com órgão judicial que concede livramento.','Pode ser público? Sim.','Beneficiários são só internos em regime fechado? Não.')
add(79,'Patronato fiscaliza prestação de serviço e limitação de fim de semana.','Colaborar na fiscalização do livramento não significa concedê-lo ou revogá-lo sozinho.','Orienta condenado à restritiva? Sim.','Toda fiscalização equivale a decisão judicial? Não.')
add(80,'Conselho da Comunidade reúne representações mínimas em cada comarca.','Falta de representação ativa escolha judicial subsidiária; consultar órgãos atuais de indicação sem presumir existência atual de toda designação histórica.','Defensor Público integra composição textual? Sim.','Composição é necessariamente um único integrante? Não.')
add(81,'Conselho visita pelo menos mensalmente e entrega relatórios ao juiz eConselho Penitenciário.','Obter recursos deve ocorrer em harmonia com direção,não usurpação de competências.','Entrevistar presos está previsto? Sim.','Relatório vai só ao Ministério da Justiça? Não.')
add('81-a','Defensoria defende necessitados coletivamente em incidente de execução.','Não é restrita à primeira instância ou a demandas individuais.','Atuação alcança todos os graus? Sim.','Defesa coletiva está excluída? Não.')
add('81-b','Defensoria requer remição,recorre e visita periodicamente.','Pedido de interdição não é interdição direta; norma fala periodicamente,sem copiar prazo mensal doMP.','Pode recorrer de decisão administrativa no recorte? Sim.','A periodicidade textual é necessariamente mensal? Não.')
add(82,'Conjunto arquitetônico comporta destinações distintas devidamente isoladas.','Compartilhar terreno não autoriza misturar todas as categorias de presos.','Egresso está entre destinatários? Sim.','A palavra separadamente permite reunir mulheres e idosos sem distinção? Não.')
add(83,'Berçário assegura cuidado e amamentação no mínimo até seis meses.','Segurança interna feminina é recorte específico,não proibição de todo técnico de outro sexo.','Seis meses é teto absoluto do cuidado? Não;é mínimo textual.','Há instalação para Defensoria? Sim.')
add(84,'Provisório é separado de condenado definitivo e pessoa ameaçada recebe local próprio.','Segregação protetiva não se confunde automaticamente com sançãoRDD.','Critérios de provisórios e definitivos são idênticos? Não.','Toda condição de funcionário público garante separação do§2º? Não;recorte da Administração da Justiça Criminal.')
add(85,'Capacidade atende estrutura e finalidade do estabelecimento.','Lotação física aparente não autoriza ignorar individualização/salubridade.','Conselho Nacional tem atribuição textual de limite máximo? Sim.','O artigo autoriza superlotação indefinida? Não.')
add(86,'Juiz define destino adequado em24 horas no recorte do§3º.','Transferência administrativa excepcional por risco iminente/grave exige comunicação imediata e decisão em24 horas; não carta branca nem prazo indefinido.','Prisão de outraUF pode ser executada em unidade daUnião? Sim.','Toda transferência dispensa juiz? Não.')
add(87,'Penitenciária se destina a condenado à reclusão no fechado.','Parágrafo tem recorte próprio de unidades paraRDD,inclusive provisório,não converter todo estabelecimento em penitenciária comum.','Colônia agrícola é o mesmo regime típico? Não.','Parágrafo exclui sempre presos provisórios? Não.')
add(88,'Cela individual tem dormitório,sanitário,lavatório e área mínima de seis metros quadrados.','Metragem sozinha não supre salubridade,aeração econdicionamento térmico.','Seis metros quadrados é área máxima? Não;mínima.','Basta metragem dispensando higiene/ventilação? Não.')
add(89,'Creche atende criança desamparada maior de seis meses e menor de sete anos no recorte legal.','Não confundir essa faixa com berçário do83 nem apresentar permanência como punição da criança.','Pessoal qualificado é requisito? Sim.','Sete anos completos está dentro da expressão menor de sete? Não.')
add(90,'Penitenciária masculina se afasta do centro sem impedir visitação.','Distância extrema que impossibilita visita não atende ressalva do artigo.','Visitação deve ser preservada no recorte? Sim.','Todo estabelecimento tem a mesma regra de localização? Não;Casa do Albergado difere.')
add(91,'Colônia agrícola destina-se ao semiaberto.','Falta de vaga não autoriza manter regime mais gravoso automaticamente; observarSúmulaVinculante56 e decisão judicial aplicável.','Colônia industrial também é prevista? Sim.','Esse artigo sozinho resolve alternativas por falta de vaga? Não.')
add(92,'Alojamento coletivo tem seleção adequada e capacidade compatível com individualização.','Não importar automaticamente área da cela individual como única regra de todo compartimento coletivo.','Salubridade do88 é remetida? Sim.','Alojamento coletivo é autorização para misturar presos indiscriminadamente? Não.')
add(93,'Casa do Albergado atende aberto e limitação de fim de semana.','Não reduzir estabelecimento apenas ao aberto nem transformar falta de vaga em regressão automática.','Limitação de fim de semana é expressa? Sim.','Penitenciária do fechado é equivalente por este artigo? Não.')
add(94,'Casa do Albergado fica no centro urbano e sem obstáculos físicos contra fuga.','Ausência de barreira não elimina condições judiciais nem obrigações do regime.','Fica separada dos demais estabelecimentos? Sim.','Ausência de muro dispensa disciplina? Não.')
add(95,'Região dispõe de pelo menos uma Casa do Albergado com cursos e serviços de orientação.','Mínimo de uma não é limite máximo nem substitui estrutura adequada.','Palestras têm local previsto? Sim.','O artigo fixa necessariamente uma por município? Não;texto fala região.')
patch(51,pontos=['Descumprir ou retardar INJUSTIFICADAMENTE nos incisosI/II.','Inobservância dos deveresII/V do39 tem recorte próprio.','Não presumir falta grave por qualquer atraso sem apuração.'])
note(53,'Remissão ao antigo parágrafo único do41 deve ser integrada ao§1º atual. Não atribuir ao diretor autorização universal para restringirV/X/XV,cuja redação atual exige ato motivado judicial.')
note(57,'RDD tem pressupostos/competência próprios; gravidade não autoriza incluí-lo por automatismo ou somar indistintamente todas as sanções.')
patch(59,simples='Apuração de falta exige defesa e decisão motivada. IntegrarSúmula533/STJ comRE972598/STF: oitiva judicial com defensor eMP no recorte reconhecido afasta PAD prévio e supre deficiência de defesa técnica administrativa; não elimina garantias.',pontos=['Defesa técnica,contraditório e motivação permanecem.','PAD é regra administrativa,mas não exigência universal apesar de audiência judicial adequada segundoSTF.','Tema758/STF dispensa trânsito criminal para falta por crime doloso,sob devido processo.'],atencao=['Não exigir PAD em toda situação nem dispensar defesa. A notícia oficial STF de7/12/2020 identifica os julgados; não certificada toda hipótese ou decisão posterior.'],remissoes=['https://noticias.stf.jus.br/postsnoticias/reconhecimento-de-falta-grave-por-crime-doloso-durante-a-execucao-dispensa-transito-em-julgado/'])
note(60,'Prazo de dez dias do isolamento preventivo não é o prazo da decisão finalRDD do54 nem elimina controle/garantias judiciais.')
patch(66,pontos=['Aplicar lei posterior favorável; decidir benefícios/incidentes e extinção nos pressupostos legais.','Inspeção mensal e atestado anual têm periodicidades distintas.','AlíneaVb tem referência residual à multa: integrarCP51,sem prisão automática por inadimplemento.'],atencao=['Não ensinar conversão de multa em prisão como regra atual por dívida. Competências não dispensam requisitos vigentes de saídas,benefícios ou monitoração.'])
for n in [71,72,74]:note(n,'LEP mantém designaçãoDEPEN; portal oficial atual identifica Secretaria Nacional dePolíticasPenais(Senappen). Distinguir texto legal histórico e estrutura administrativa atual; não certificadas todas as atribuições regulamentares posteriores.','https://www.gov.br/senappen/pt-br/acesso-a-informacao/institucional')
patch(71,simples='No texto daLEP,DEPEN é órgão executivo penitenciário nacional com apoio aoCNPCP. A organização administrativa atual deve ser distinguida: portal oficial apresentaSenappen(Secretaria Nacional dePolíticasPenais),sem reescrever o texto compilado como se o nome antigo bastasse à estrutura atual.',termos=[dict(termo='DEPEN/Senappen',significado='Designação constante do texto legal e identificação institucional atual,que não devem ser confundidas.')])
note(77,'Referência à ascensão funcional não autoriza provimento de cargo de carreira diversa sem concurso e regime constitucional aplicável. Formação/reciclagem e ingresso são questões distintas.')
note(80,'Expressões de órgãos de indicação no texto precisam de integração à representação profissional atual. Não certificada toda regulamentação de composição local ou equiparação automática de órgãos históricos.')
note('81-b','Competência de requerer,recorrer e fiscalizar não equivale a julgar/interditar diretamente. Visita textual periódica não pode virar mensal universal por cópia do68.')
patch(83,pontos=['Assistência,educação,trabalho,recreação/esporte conforme natureza.','Berçário: no mínimo até seis meses;não teto automático.','Segurança das dependências internas femininas: agentes do sexo feminino no recorte expresso.','Salas de aula,estágio eDefensoria previstos.'])
patch(86,pontos=['Execução pode ocorrer em outraUF ou estabelecimento daUnião.','§3º: decisão judicial em24 horas sob requerimento e requisitos.','§5º: risco iminente/grave,transferência excepcional,comunicação imediata e decisão judicial em24 horas.','§4º contém alteração deLei15.410/2026; não certificado todo controle/efeito temporal dessa hipótese.'],atencao=['Não generalizar urgência a qualquer transferência ou apresentar decisão judicial como facultativa em toda hipótese. Lei15.410: consulta suplementar retornou503/403; não gerados exercícios de aplicação automática do§4º.'])
for n in [87,91,93]:note(n,'Destinação legal de unidade não autoriza manter preso em regime mais gravoso só por falta de vaga. Aplicação concreta depende de decisão e parâmetros constitucionais pertinentes; sem fórmula universal de prisão domiciliar.')
# Improve readability of the deliberately explicit prose; URLs remain exact.
import re
for row in rows.values():
 for field in ['simples','exemplo','pontos','atencao']:
  def readable(v):return re.sub(r'(?<=[a-zà-ú])(?=[A-ZÀ-Ú])',' ',v)
  row[field]=readable(row[field]) if isinstance(row[field],str) else [readable(v) for v in row[field]]
save(47)
